});

test('lineTotal: happy path', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const line = result.value.lines[0];
  const total = require('../src/invoices.js').lineTotal(line);

  assert.deepEqual(total, { ok: true, value: 95000 }); // 10 * 9500
});

test('lineTotal: calculates correctly for different quantities', () => {
  const { lineTotal } = require('../src/invoices.js');

  const result1 = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(result1.ok, true);
  assert.equal(result1.value, 42500);

  const result2 = lineTotal({ qty: 1, unitPrice: 120000 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value, 120000);

  const result3 = lineTotal({ qty: 100, unitPrice: 37 });
  assert.equal(result3.ok, true);
  assert.equal(result3.value, 3700);
});

test('lineTotal: invalid - missing qty', () => {
  const { lineTotal } = require('../src/invoices.js');

  const result = lineTotal({ unitPrice: 9500 });
  assert.deepEqual(result, { ok: false, error: 'LINE_INVALID' });
});

test('lineTotal: invalid - qty is zero', () => {
  const { lineTotal } = require('../src/invoices.js');

  const result = lineTotal({ qty: 0, unitPrice: 9500 });
