test('invoiceTotals: happy path with single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const { invoiceTotals } = require('../src/invoices.js');
  const totals = invoiceTotals(result.value);

  assert.deepEqual(totals, {
    ok: true,
    value: { subtotal: 95000, total: 95000 },
  });
});

test('invoiceTotals: happy path with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000
      { sku: 'COPY-HOUR', qty: 3 }, // 3 * 6000 = 18000
    ],
  });

  const { invoiceTotals } = require('../src/invoices.js');
  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 155500); // 42500 + 95000 + 18000
  assert.equal(totals.value.total, 155500);
});

test('invoiceTotals: total equals subtotal for now', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const { invoiceTotals } = require('../src/invoices.js');
  const totals = invoiceTotals(result.value);

  assert.equal(totals.value.total, totals.value.subtotal);
});

test('invoiceTotals: invalid - invoice is null', () => {
  const { invoiceTotals } = require('../src/invoices.js');

  const result = invoiceTotals(null);
  assert.deepEqual(result, { ok: false, error: 'INVOICE_INVALID' });
});

test('invoiceTotals: invalid - invoice is undefined', () => {
