  const result = invoiceTotals({ customerId: 'C-001' });
  assert.deepEqual(result, { ok: false, error: 'INVOICE_INVALID' });
});

test('invoiceTotals: invalid - lines is not an array', () => {
  const { invoiceTotals } = require('../src/invoices.js');

  const result = invoiceTotals({ lines: 'not-an-array' });
  assert.deepEqual(result, { ok: false, error: 'INVOICE_INVALID' });
});

test('invoiceTotals: invalid - propagates line errors', () => {
  const { invoiceTotals } = require('../src/invoices.js');

  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, name: 'Dev', unitPrice: 9500, vatRate: 21 },
      { sku: 'DES-HOUR', qty: 0, name: 'Design', unitPrice: 8500, vatRate: 21 }, // invalid
    ],
  };

  const result = invoiceTotals(invoice);
  assert.deepEqual(result, { ok: false, error: 'LINE_INVALID' });
});

test('invoiceTotals: large invoice with many lines', () => {
  const lines = [];
  for (let i = 0; i < 10; i++) {
    lines.push({ sku: 'DEV-HOUR', qty: 5 });
  }

  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines,
  });

  const { invoiceTotals } = require('../src/invoices.js');
  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 475000); // 10 * (5 * 9500)
});

