test('invoiceTotals: happy path with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000
      { sku: 'COPY-HOUR', qty: 3 }, // 3 * 6000 = 18000
    ],
  });

  const { invoiceTotals } = require('../src/invoices.js');
  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 155500); // 42500 + 95000 + 18000
  assert.equal(totals.value.total, 155500);
});

